"""Derives Test-HostNativeDamage-v1274.ps1 from make_hostworld_damage_v1272.py's harness for stage 4 (#14, 1214x): the
host player's own grenade explosion on a combat-bound guard. The lab item fixture cannot grant a grenade under the
product controller (take 1273a: unsupported_scope_or_item_owned), so the lab-only `coop_npc_combat hostnative_test`
sends the native explosion_grenade damage (native amount; attacker and inflictor the local player) through the
installed damage observer at the Dunwall tutorial guard. Before 1214w the capture suppressed such player damage and
retired the guard. Pass (runtime): the hit lands on the host (hostNativePassed), and the guard ends in the same state
in both worlds: equal health (HostWorld) or dead in both (Dead)."""
from pathlib import Path
P = Path(__file__).resolve().parent
src = P.joinpath('make_hostworld_damage_v1272.py').read_text(encoding='utf-8')
def rep(old, new):
    global src
    assert src.count(old) == 1, old[:70]; src = src.replace(old, new)
rep("[string]$Take='hostworld-damage-v1272a',[string]$Candidate='candidate-npc-combat-v1214r',[int]$Hits=3)", "[string]$Take='hostnative-damage-v1274a',[string]$Candidate='candidate-npc-combat-v1214x',[int]$Hits=1)")
rep("'# 1272 (stage 4, #14, 1214r): host-world damage on a combat-bound guard. Generated by make_hostworld_damage_v1272.py from 1248l.'",
    "'# 1274 (stage 4, #14, 1214x): the host player\\'s own grenade explosion on a combat-bound guard. Generated by make_hostnative_damage_v1274.py from 1248l.'")
rep("operation='HostWorld1272'\").replace('sources=$Sources'", "operation='HostNative1274'\").replace('sources=$Sources'")
rep("C host 'coop_npc_combat hostworld_test';Start-Sleep -Milliseconds 1800", "C host 'coop_npc_combat hostnative_test';Start-Sleep -Milliseconds 3500")
rep("$t=S host '.npc-hostworld-test.json';$after=[ordered]@{host=(Q host '--health' $g.handle).current;client=(Q client '--health' $og.handle).current}",
    "$t=S host '.npc-hostworld-test.json';$after=[ordered]@{host=$(try{(Q host '--health' $g.handle).current}catch{$null});client=$(try{(Q client '--health' $og.handle).current}catch{$null})}")
rep("host=($hc|Select-Object result,hostWorldPassed,hostWorldCommitted,committed,lastRetire);client=($cc|Select-Object result,hostWorldApplied,followSubtractions,applied,lastRetire)})",
    "host=($hc|Select-Object result,hostNativePassed,hostNativeLast,hostWorldCommitted,committed,deaths,lastRetire);client=($cc|Select-Object result,hostWorldApplied,followSubtractions,applied,deaths,lastRetire);hostRelevance=((S host '.npc-stream.json').relevance|Select-Object deadReconciled,deadSent);clientRelevance=((S client '.npc-stream.json').relevance|Select-Object clientDeadApplied,clientDeadAlready,clientDeadRefused,clientDeadLast)})")
rep("if($t.result-ne'damaged'){throw \"Hit ${i}: host-world damage not applied ($($t.result))\"}", "if($t.result-ne'damaged'-or$t.mode-ne'hostnative'){throw \"Hit ${i}: host grenade damage not applied ($($t.mode) $($t.result))\"}")
rep("if($after.host-ne$after.client){throw \"Hit ${i}: guard health differs (host $($after.host), client $($after.client))\"}",
    "$dh=($null-eq$after.host)-or[double]$after.host-le0;$dc=($null-eq$after.client)-or[double]$after.client-le0\n"
    "   if($dh-ne$dc){throw \"Hit ${i}: guard dead in one world only (host $($after.host), client $($after.client))\"}\n"
    "   if(!$dh-and$after.host-ne$after.client){throw \"Hit ${i}: guard health differs (host $($after.host), client $($after.client))\"}")
rep("""  $row.counters=[ordered]@{hostWorldPassed=$hc.hostWorldPassed;hostWorldCommitted=$hc.hostWorldCommitted;clientHostWorldApplied=$cc.hostWorldApplied;clientFollowSubtractions=$cc.followSubtractions}
  if($hc.hostWorldCommitted-lt$Hits-or$cc.hostWorldApplied-lt$Hits){throw "HostWorld commits $($hc.hostWorldCommitted), applied $($cc.hostWorldApplied), expected $Hits"}
  $row.checks.Add("$Hits host-world hits shared as HostWorld commits; the client followed each")""",
"""  $row.counters=[ordered]@{hostNativePassed=$hc.hostNativePassed;hostNativeLast=$hc.hostNativeLast;hostWorldCommitted=$hc.hostWorldCommitted;clientHostWorldApplied=$cc.hostWorldApplied}
  if($hc.hostNativePassed-lt$Hits-or$hc.hostNativeLast-ne'components/equipment/damage/explosion_grenade.damage'){throw "The host capture did not pass the grenade natively ($($hc.hostNativePassed), $($hc.hostNativeLast))"}
  $row.checks.Add('The host grenade explosion passed the capture natively (hostNativePassed) and the guard ends in the same state in both worlds')""")
rep("Save \"$out/hostworld.json\"", "Save \"$out/hostnative.json\"")
rep("try{Restore 'hostworld';", "try{Restore 'hostnative';")
rep("operation='HostWorld1272'\") for l in end]", "operation='HostNative1274'\") for l in end]")
rep("\"scope='Stage 4 host-world damage: under the product controller the host applies lab-only bloodfly damage (another NPC as source) to the combat-bound Dunwall tutorial guard through the installed damage observer; the client replica must follow every hit (HostWorld); fixture restored.'\"",
    "\"scope='Stage 4 host player damage the replay cannot reproduce: under the product controller the lab-only hostnative_test sends the native grenade explosion (local player as attacker and inflictor) to the combat-bound Dunwall tutorial guard through the installed damage observer; it must apply natively and the guard end in the same state in both worlds (1214w/1214x); fixture restored.'\"")
rep("'\"PASS_HOSTWORLD_DAMAGE\"'", "'\"PASS_HOSTNATIVE_DAMAGE\"'")
rep("P.joinpath('Test-HostWorldDamage-v1272.ps1')", "P.joinpath('Test-HostNativeDamage-v1274.ps1')")
exec(compile(src.split('"""', 2)[2], 'make_hostnative_inner', 'exec'))
